"""Task-local inspection: list workspace files and inspect any SQLite DBs."""

import os
import sqlite3

ROOT = os.getcwd()

print("=== Workspace contents ===")
for entry in sorted(os.listdir(ROOT)):
    full = os.path.join(ROOT, entry)
    kind = "dir" if os.path.isdir(full) else "file"
    print(f"{kind:4s} {entry}")

print("\n=== Candidate SQLite databases ===")
candidates = [
    name
    for name in os.listdir(ROOT)
    if name.endswith((".db", ".sqlite", ".sqlite3", ".db3"))
]
if not candidates:
    print("(none found)")

for name in candidates:
    path = os.path.join(ROOT, name)
    print(f"\n--- {name} ---")
    try:
        with sqlite3.connect(path) as conn:
            tables = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
            ).fetchall()
            print("tables:", [t[0] for t in tables] or "(none)")
            for (t,) in tables:
                cols = conn.execute(f"PRAGMA table_info({t})").fetchall()
                print(f"  {t}: " + ", ".join(f"{c[1]} {c[2]}" for c in cols))
    except sqlite3.Error as exc:
        print(f"  could not open: {exc}")

